import type { NativeContourPayload } from './NativeContourRecordViewer';
import type { NativeContourVerification } from './native-contour-verification.js';
export type DiagnosticLimits = { centroidShiftMicrometre: number; areaRatio: number; cyclicRmsMicrometre: number };
export type DiagnosticContour = { id: string; sourceName: string; sourceOrderIndex: number; vertexCount: number; zValuesMicrometre: number[]; zeroLengthEdgeIndices: number[]; selfIntersectionEdgePairs: number[][] | null; areaCalculable: boolean };
export type DiagnosticTransition = { fromContourId: string; toContourId: string; fromZMicrometre: number; toZMicrometre: number; zGapMicrometre: number; centroidShiftMicrometre: number; areaRatio: number; cyclicRmsMicrometre: number; phaseShiftAt128Samples: number; bothSourceContoursSimple: boolean; zeroLengthSourceEdges: number };
export type DiagnosticGroup = { sourceName: string; status: 'numeric_z_neighbours_available' | 'not_comparable'; reasons: string[]; nonPlanarContourIds: string[]; repeatedZ: { zMicrometre: number; contourIds: string[] }[]; sourceOrder: DiagnosticContour[]; sortedContourIds: string[]; transitions: DiagnosticTransition[] };
export type DiagnosticSummary = { sourceContourCount: number; sourceVertexCount: number; sourceNameGroupCount: number; comparableGroupCount: number; notComparableGroupCount: number; numericNeighbourIntervalCount: number };
export type NativeContourAnalysis = { neuronId: number; sourceFrame: string; sourceContext: unknown; sourceIdentity: unknown; summary: DiagnosticSummary; groups: DiagnosticGroup[] };
export type DiagnosticEvaluation = { parameters: DiagnosticLimits; summary: DiagnosticSummary & { intervalsWithinNumericalLimits: number; intervalsWithinLimitsAndClearSourceTopology: number }; groups: (Omit<DiagnosticGroup, 'transitions'> & { transitions: (DiagnosticTransition & { numericalLimitsMet: boolean; sourceTopologyClear: boolean; screenMet: boolean })[] })[] };
export type NativeContourDiagnosticReceipt = { documentType: 'native_contour_numeric_diagnostic_receipt'; schemaVersion: '0.1.0'; analysisBuild: typeof NATIVE_CONTOUR_DIAGNOSTIC_BUILD; source: { neuronId: number; sourceFrame: string; sourceContext: unknown; sourceIdentity: unknown }; verification: NativeContourVerification; method: Record<string, unknown>; scientificScope: Record<string, unknown>; report: DiagnosticEvaluation };
export const NATIVE_CONTOUR_DIAGNOSTIC_LIMITS: Readonly<DiagnosticLimits>;
export const NATIVE_CONTOUR_DIAGNOSTIC_PRESETS: Readonly<Record<keyof DiagnosticLimits, readonly number[]>>;
export const NATIVE_CONTOUR_DIAGNOSTIC_BUILD: Readonly<{ applicationVersion: string; scope: string; inputs: readonly { path: string; bytes: number; sha256: string }[] }>;
export function analyseNativeContourGroups(neuronId: number, payload: NativeContourPayload): NativeContourAnalysis;
export function evaluateNativeContourDiagnostics(analysis: NativeContourAnalysis, parameters?: DiagnosticLimits): DiagnosticEvaluation;
export function nativeContourDiagnosticSensitivity(analysis: NativeContourAnalysis): { parameters: DiagnosticLimits; groups: { sourceName: string; intervalCount: number; withinNumericalLimits: number; withinLimitsAndClearSourceTopology: number }[] }[];
export function createNativeContourDiagnosticReceipt(analysis: NativeContourAnalysis, parameters?: DiagnosticLimits): NativeContourDiagnosticReceipt;
export function validateNativeContourDiagnosticReceipt(receipt: NativeContourDiagnosticReceipt, neuronId: number, payload: NativeContourPayload): NativeContourDiagnosticReceipt;
export function nativeContourDiagnosticCsv(analysis: NativeContourAnalysis, parameters?: DiagnosticLimits): string;
